xml.Script:
        Colors[ 0] := 'FFFFFF'; // White
        Colors[ 1] := 'FFFF00'; // Yellow
        Colors[ 2] := '0000CC'; // Blue
        Colors[ 3] := 'FF0000'; // Red
        Colors[ 4] := '00AA00'; // Green
        Colors[ 5] := '800080'; // Violett
        Colors[ 6] := 'FFFFAA'; // Cream
        Colors[ 7] := '0066CC'; // LightBlue
        Colors[ 8] := 'FF6000'; // Orange
        Colors[ 9] := '00FF00'; // LightGreen
        Colors[10] := 'FF88CC'; // LightViolett
        Colors[11] := '666666'; // Gray

        W := 0.6;

        a := W;
        k := 0.7; // oval
        D := 2 * W / 6.8;

        z[0] :=-W;
        r[0] := 0;
        for i := 1 to 7 do begin
            z[i] := D * (i - 4);
            r[i] := sqrt(W^2 - z[i]^2) * k;
        end;
        z[8] := W;
        r[8] := 0;

        for i := 0 to 5 do begin
            ax[i] := sin(i * Pi/6);
            ay[i] := cos(i * Pi/6);
        end;

        xc[0] := 0;
        yc[0] := 0;
        zc[0] := z[0];
        c := 1;
        for i := 1 to 7 do begin
            for j := 0 to 11 do begin
                xc[c] := r[i] * sin(j * Pi/6);
                yc[c] := r[i] * cos(j * Pi/6);
                zc[c] := z[i];
                Inc(c);
            end;
        end;
        xc[c] := 0;
        yc[c] := 0;
        zc[c] := z[8];
